 private UsernamePasswordAuthenticationToken auth(boolean escribir,boolean financiero,boolean revertir){var ps=new ArrayList<>(List.of("EMPLEADO_LEER","EMPLEADO_LABORAL_LEER",escribir?"CONDICION_SALARIAL_ADMINISTRAR":"CONDICION_SALARIAL_LEER"));if(financiero)ps.add("MOVIMIENTO_FINANCIERO_REGISTRAR");if(revertir)ps.add("MOVIMIENTO_FINANCIERO_REVERTIR");var a=ps.stream().map(SimpleGrantedAuthority::new).toList();return new UsernamePasswordAuthenticationToken(new UsuarioPrincipal(440000L,440000L,Set.of(),true,false,"qa.pagos","",a),"",a);}
 private void sesion(){SecurityContextHolder.getContext().setAuthentication(auth(true,true,true));}
 private MockHttpSession web(boolean editar){var s=new MockHttpSession();s.setAttribute("SPRING_SECURITY_CONTEXT",new SecurityContextImpl(auth(editar,editar,editar)));return s;}
 private PagoEmpleadoNominaForm pago(PreparacionNominaService s,Long b){var f=new PagoEmpleadoNominaForm();f.setVersion(s.obtener(b).version());f.setCuentaId(440000L);f.setMotivoPagoId(440000L);f.setReferencia("PAGO-QA-FICTICIO");f.setMotivo("Operación de capacitación en base aislada");f.setConfirmado(true);return f;}
 private Long periodo(ProgramacionNominaService p,Long cal,int mes){var c=p.contexto(cal);var f=new PeriodoNominaForm();f.setCalendarioId(cal);f.setCalendarioTexto(c.calendario());f.setCalendarioVersion(c.version());f.setCodigo("PAGO-2030-"+mes);f.setNombre("Periodo ficticio pago "+mes);f.setInicio(LocalDate.of(2030,mes,1));f.setFin(f.getInicio().withDayOfMonth(f.getInicio().lengthOfMonth()));f.setPago(f.getFin());f.setMotivo("Prueba aislada");return p.guardarPeriodo(null,f);}
 private Long guardar(PreparacionNominaService s,Long periodo,boolean todos){UUID vista=s.prepararPeriodo(periodo,todos?"TODOS":"INDIVIDUAL");if(!todos)s.seleccionarPreparacion(vista,0L,440010L,true);return s.guardarPreparacion(vista,todos?0L:1L,null,null);}
 private Long fila(PreparacionNominaService s,Long b,int posicion){return s.guardados(b,s.obtener(b).revision(),0).getContent().get(posicion).id();}
